"use strict";(self.webpackChunkbed_mega_textbook=self.webpackChunkbed_mega_textbook||[]).push([[8368],{3495(e,t,n){n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>c,default:()=>u,frontMatter:()=>r,metadata:()=>i,toc:()=>d});const i=JSON.parse('{"id":"eed-313/unit-02/unit-teacher-notes","title":"Unit 2 teacher notes","description":"EED-313 Unit 2 tutor guidance: sequencing the three topics, the misconceptions to probe, managing the activities, and practicum links for curriculum, the four-stage cycle and differentiation.","source":"@site/licence/eed-313/unit-02/unit-teacher-notes.mdx","sourceDirName":"eed-313/unit-02","slug":"/eed-313/unit-02/unit-teacher-notes","permalink":"/licence/eed-313/unit-02/unit-teacher-notes","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Unit 2 teacher notes","description":"EED-313 Unit 2 tutor guidance: sequencing the three topics, the misconceptions to probe, managing the activities, and practicum links for curriculum, the four-stage cycle and differentiation.","course_code":"EED-313","unit_no":2,"clo_refs":["SLO:EED-313-2-3","SLO:EED-313-2-4"],"blooms_summary":"Guidance for tutors sequencing Unit 2: how to move trainees from seeing curriculum as content to seeing it as a management act; how to run the three topic activities; what misconceptions to probe; and how to design the practicum tasks so they produce usable evidence.","est_reading_minutes":6,"translation_status":"draft"},"sidebar":"licenceSidebar","previous":{"title":"Unit 2 assessment","permalink":"/licence/eed-313/unit-02/unit-assessment"},"next":{"title":"Routines, schedules, and time management","permalink":"/licence/eed-313/unit-03/"}}');var s=n(4848),o=n(8453),a=n(6606);const r={title:"Unit 2 teacher notes",description:"EED-313 Unit 2 tutor guidance: sequencing the three topics, the misconceptions to probe, managing the activities, and practicum links for curriculum, the four-stage cycle and differentiation.",course_code:"EED-313",unit_no:2,clo_refs:["SLO:EED-313-2-3","SLO:EED-313-2-4"],blooms_summary:"Guidance for tutors sequencing Unit 2: how to move trainees from seeing curriculum as content to seeing it as a management act; how to run the three topic activities; what misconceptions to probe; and how to design the practicum tasks so they produce usable evidence.",est_reading_minutes:6,translation_status:"draft"},c="Unit 2 teacher notes",h={},d=[{value:"Sequencing note",id:"sequencing-note",level:2},{value:"Common misconceptions to probe",id:"common-misconceptions-to-probe",level:2},{value:"Managing the activities",id:"managing-the-activities",level:2},{value:"Practical work and practicum links",id:"practical-work-and-practicum-links",level:2},{value:"A note on the figures",id:"a-note-on-the-figures",level:2},{value:"Assessment note",id:"assessment-note",level:2}];function l(e){const t={h1:"h1",h2:"h2",header:"header",li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,o.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(a.A,{}),"\n",(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"unit-2-teacher-notes",children:"Unit 2 teacher notes"})}),"\n",(0,s.jsx)(t.h2,{id:"sequencing-note",children:"Sequencing note"}),"\n",(0,s.jsx)(t.p,{children:"The three topics follow the logic of a single plan. Topic 2.1 (curriculum as a management tool) asks trainees to see that management begins before the lesson, in the decisions a teacher makes about content, sequence, pace and grouping. Topic 2.2 (plan, motivate, teach, assess) walks through the cycle that carries that plan from intention to evidence. Topic 2.3 (differentiation, multigrade and overcrowding) asks how to adapt the plan when the pupils or the room make one-size-fits-all impossible."}),"\n",(0,s.jsx)(t.p,{children:"A useful session order is to teach the topics in numerical order across the four weeks the guide allows (Weeks 5 to 8), using the first session of the unit to surface trainees' own planning habits and the last to rehearse the integrative assessment. The unit is designed so that a tutor who needs to compress it can merge the activity time of Topics 2.1 and 2.2 into a single planning workshop without losing the conceptual spine."}),"\n",(0,s.jsx)(t.h2,{id:"common-misconceptions-to-probe",children:"Common misconceptions to probe"}),"\n",(0,s.jsx)(t.p,{children:"These are the misconceptions the unit names explicitly. Surface them early and return to them; trainees often assent to the correct version in a discussion and then revert to the misconception when they plan."}),"\n",(0,s.jsxs)(t.ol,{children:["\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:'"Differentiation means making some children do easier work."'}),' This is the most persistent one. Probe it by asking: "If the target is the same but the support is different, is that easier?" Trainees who have taught or been taught in tracked systems will find this counter-intuitive. The figure in Topic 2.3 (one objective, three versions) is designed to make the distinction visible; use it as a poster or handout.']}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:'"Multigrade teaching is just teaching two lessons at once."'}),' Probe it by asking: "If the teacher is working with Grade 3, what is Grade 4 doing?" The anchor activity is the answer, and the question "what is the other grade doing?" is the management question every multigrade teacher must be able to answer.']}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:'"An overcrowded class cannot be managed, only survived."'}),' Probe it by asking: "What is one routine that works better with sixty pupils than with twenty?" Whole-class anchors and structured routines are the answer. The survival mindset is the real enemy, because it stops the teacher from investing in the routines that make the room run.']}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:'"I just follow the textbook, so I don\'t make curriculum decisions."'}),' This one belongs to Topic 2.1. Probe it by asking: "Did you skip anything in the chapter? Did you spend more time on one idea than another? Did you put pupils in pairs or rows?" Every yes is a curriculum decision the teacher made without naming it.']}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(t.h2,{id:"managing-the-activities",children:"Managing the activities"}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 2.1 - One objective, three plans (25 minutes)."}),' Give trainees the objective on a slide or handout before they form groups. The key teaching move is the debrief question: "What changed because of the room, not because of the mathematics?" If trainees answer "the content," push them back: the objective is the same; what changed is the route. Collect one example per group on the board and sort them by the constraint they respond to.']}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 2.2 - Trace a lesson through the cycle (20 minutes)."})," Pairs work better than groups of three here because the task is a structured trace, not a design. Ask each pair to choose a lesson every trainee in the room has seen - a shared school memory works well - so the debrief can surface disagreement about which stage a given move belonged to. The disagreement is the teaching point: the stages are not always cleanly separated in real lessons, and the management decision at each stage is often invisible to the pupils."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 2.3 - Differentiate one objective (20 minutes)."}),' This is the most cognitively demanding activity. The trap is that trainees produce three versions that differ in target rather than in route. The debrief question - "identify one moment where a pupil might slip from scaffolded to easier, and explain how your plan prevents it" - is designed to catch this. If trainees cannot answer it, they have made work easier, not differentiated.']}),"\n",(0,s.jsx)(t.h2,{id:"practical-work-and-practicum-links",children:"Practical work and practicum links"}),"\n",(0,s.jsx)(t.p,{children:'Each topic carries a "Try this at your practicum school" task. The unit works best when the tutor sets these up explicitly before trainees leave for practicum and debriefs them when trainees return.'}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 2.1 practicum task"})," (one week of curriculum-decision notes) produces a short reflection. Use it to open Topic 2.2: ask trainees which of their four decisions made the most difference, and use their examples to motivate the four-stage cycle."]}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 2.2 practicum task"})," (a time tally across three lessons) produces a simple data set. Use it to make the point that most teachers underestimate how little time they spend on assessment, and that the return arrow from assess to plan is the loop least often closed."]}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Topic 2.3 practicum task"})," (observe a multigrade or overcrowded classroom) produces the evidence trainees need for ERQ 2 or ERQ 5. If the practicum school has neither a multigrade nor an overcrowded room, ask trainees to observe a single-grade room and note the tactics the teacher uses that would stop working if the class doubled in size."]}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(t.h2,{id:"a-note-on-the-figures",children:"A note on the figures"}),"\n",(0,s.jsx)(t.p,{children:"The unit carries six figures: two concept-map or diagram figures that make a conceptual structure visible (fig-U2-1, fig-U2-3), one flowchart that sequences a cycle (fig-U2-2), and three tables that compare options against a criterion (fig-U2-4, fig-U2-5, fig-U2-6). The tables are the ones trainees most often try to read as prose. Before you project any of them, ask trainees to read the column headers first and say what the table is comparing. That habit transfers to the textbook tables they will use in their own teaching."}),"\n",(0,s.jsx)(t.h2,{id:"assessment-note",children:"Assessment note"}),"\n",(0,s.jsx)(t.p,{children:"The 10/10/5 bank is designed to be used in two passes: the MCQs and RRQs as formative checks at the end of Topics 2.2 and 2.3, and the ERQs as a summative task at the end of the unit. ERQ 5 (the integrative item) is the one that most reliably separates trainees who have understood the unit from those who have memorised its definitions. If you use only one ERQ, use that one."})]})}function u(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(l,{...e})}):l(e)}},6606(e,t,n){n.d(t,{A:()=>s});n(6540);var i=n(4848);function s(e){var t=e.label,n=void 0===t?"Print / Save as PDF":t;return(0,i.jsxs)("button",{type:"button",className:"print-handout print-hidden","aria-label":"Print or save this handout as a PDF",onClick:function(){return"undefined"!=typeof window&&window.print()},children:[(0,i.jsx)("span",{"aria-hidden":"true",children:"\ud83d\udda8 "}),n]})}},8453(e,t,n){n.d(t,{R:()=>a,x:()=>r});var i=n(6540);const s={},o=i.createContext(s);function a(e){const t=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),i.createElement(o.Provider,{value:t},e.children)}}}]);